def _validate_input(data: pd.DataFrame) -> None:
    """Reject invalid history without dropping, filling, or reordering rows."""
    missing = set(REQUIRED_COLUMNS) - set(data.columns)
    if missing:
        raise ValueError(f"Missing required columns: {sorted(missing)}")
    if data.empty:
        raise ValueError("History is empty")
    dates = pd.to_datetime(data["date"], errors="raise")
    if dates.isna().any() or dates.duplicated().any():
        raise ValueError("Missing or duplicate dates")
    if not dates.is_monotonic_increasing:
        raise ValueError("Dates must be in ascending order")
    values = data.loc[:, REQUIRED_COLUMNS[1:]]
    if not all(pd.api.types.is_numeric_dtype(values[col]) for col in values):
        raise ValueError("OHLCV fields must be numeric")
    if not np.isfinite(values.to_numpy(dtype=float)).all():
        raise ValueError("Unexpected missing or non-finite OHLCV data")
    if (values.loc[:, ["open", "high", "low", "close"]] <= 0).any().any():
        raise ValueError("Prices must be positive")
    if (values["volume"] < 0).any():
        raise ValueError("Volume must be nonnegative")

def _check_features(features: pd.DataFrame) -> pd.Series:
    """Require sorted, unique NVDA sessions; reject invalid input without repair."""
    required = {"date", "ticker", "open", "close"}
    if features.empty or not required <= set(features):
        raise ValueError(f"Nonempty feature matrix requires {sorted(required)}")
    if features.columns.duplicated().any():
        raise ValueError("Duplicate feature column names")
    if not features.ticker.eq("NVDA").fillna(False).all():
        raise ValueError("Stage 8 supports exactly ticker == NVDA; mixed tickers are rejected")
    dates = parse_dates(features.date)
    if dates.duplicated().any():
        raise ValueError("Duplicate ticker/trading-date observations")
    if not dates.is_monotonic_increasing:
        raise ValueError("Trading dates must be ascending; no sorting or row removal is performed")
    if any(c.startswith(("target_", "forward_return_")) for c in features.columns):
        raise ValueError("Source X must not contain target columns")
    bad = invalid_price_count(features)
    if bad:
        raise ValueError(f"Invalid open/close prices in {bad} rows; finite positive numeric prices required")
    return dates

def invalid_price_count(features: pd.DataFrame) -> int:
    """Count rows violating the strict numeric, finite, positive open/close contract."""
    invalid = np.zeros(len(features), dtype=bool)
    for column in ("open", "close"):
        if column not in features:
            return len(features)
        values = features[column]
        if (not pd.api.types.is_numeric_dtype(values) or pd.api.types.is_bool_dtype(values)
                or pd.api.types.is_complex_dtype(values)):
            invalid |= np.ones(len(features), dtype=bool)
        else:
            numbers = values.to_numpy(dtype=float, na_value=np.nan)
            invalid |= ~np.isfinite(numbers) | (numbers <= 0)
    return int(invalid.sum())

def standardize_history(data: pd.DataFrame, symbol: str | None = None) -> pd.DataFrame:
    """Normalize historical OHLCV data to the project CSV schema."""
    if data.empty:
        raise ValueError(f"No historical data returned for {symbol or 'symbol'}")

    frame = _flatten_yfinance_columns(data)
    frame = frame.reset_index()
    frame.columns = [_normalize_column_name(column) for column in frame.columns]

    rename_map = {
        "datetime": "date",
    }
    if "date" not in frame.columns:
        rename_map["index"] = "date"
    frame = frame.rename(columns=rename_map)

    missing = [column for column in REQUIRED_COLUMNS if column not in frame.columns]
    if missing:
        raise ValueError(f"Missing required columns for {symbol or 'symbol'}: {missing}")

    result = frame.loc[:, REQUIRED_COLUMNS].copy()
    result["date"] = pd.to_datetime(result["date"]).dt.date
    for column in ("open", "high", "low", "close", "volume"):
        result[column] = pd.to_numeric(result[column], errors="coerce")

    result = result.dropna(subset=list(REQUIRED_COLUMNS))
    result = result.drop_duplicates(subset="date", keep="last")
    result = result.sort_values("date").reset_index(drop=True)

    if result.empty:
        raise ValueError(f"No valid historical rows after standardization for {symbol or 'symbol'}")

    return result

def _flatten_yfinance_columns(data: pd.DataFrame) -> pd.DataFrame:
    """Return a copy with yfinance MultiIndex columns reduced to field names."""
    frame = data.copy()
    if not isinstance(frame.columns, pd.MultiIndex):
        return frame

    required_names = {"open", "high", "low", "close", "volume"}
    for level in range(frame.columns.nlevels):
        names = {_normalize_column_name(value) for value in frame.columns.get_level_values(level)}
        if required_names.issubset(names):
            frame.columns = frame.columns.get_level_values(level)
            return frame

    frame.columns = ["_".join(str(part) for part in column if part) for column in frame.columns]
    return frame

def _market(market: pd.DataFrame) -> pd.DataFrame:
    result = market.copy().reset_index(drop=True)
    if "date" not in result or result.empty:
        raise ValueError("Nonempty market dates required")
    dates = parse_dates(result.date)
    if dates.isna().any() or dates.duplicated().any() or not dates.is_monotonic_increasing:
        raise ValueError("Market dates must be unique, nonmissing and ascending")
    if not dates.eq(dates.dt.normalize()).all() or dates.dt.tz is not None:
        raise ValueError("Expected timezone-naive calendar dates")
    if "ticker" in result and not result.ticker.eq("NVDA").all():
        raise ValueError("Market ticker must be NVDA")
    result["ticker"] = "NVDA"
    return result

def effective_dates(filing_dates: pd.Series, dates: pd.Series) -> pd.Series:
    """First observed session strictly after each filing, with coverage censoring."""
    sessions = pd.DatetimeIndex(parse_dates(dates))
    if sessions.has_duplicates or not sessions.is_monotonic_increasing:
        raise ValueError("Observed sessions must be unique and ascending")
    positions = sessions.searchsorted(parse_dates(filing_dates), side="right")
    return pd.Series(
        [sessions[p] if p < len(sessions) else pd.NaT for p in positions],
        index=filing_dates.index, dtype="datetime64[ns]",
    )

def _observations(
    fundamentals: pd.DataFrame, dates: pd.Series, *, allow_empty: bool = False,
) -> pd.DataFrame:
    fundamentals = normalize_fundamental_dates(fundamentals)
    quality = validate_fundamentals(fundamentals)
    if not quality["valid"] and not (allow_empty and quality["errors"] == ["No observations"]):
        raise ValueError(f"Invalid fundamentals: {quality['errors']}")
    internal = {"_filed", "_period_start", "_period_end", "_quarter", "_amended"}
    reserved = internal | {"effective_date"}
    if reserved & set(fundamentals):
        raise ValueError(f"Reserved fundamental columns: {sorted(reserved & set(fundamentals))}")
    selected = fundamentals[fundamentals.data_period_type.isin(["quarterly", "annual"])].copy()
    selected["_filed"] = parse_dates(selected.filing_date)
    selected["_period_start"] = parse_dates(selected.period_start)
    selected["_period_end"] = parse_dates(selected.period_end)
    # No guessed weekday calendar: right insertion excludes the filing day,
    # including weekends/holidays. Dates outside coverage are range-censored.
    selected["effective_date"] = effective_dates(selected._filed, dates)
    selected = selected[selected.effective_date.notna()].copy()
    selected["_quarter"] = selected.data_period_type.eq("quarterly").astype(int)
    selected["_amended"] = selected.form.str.endswith("/A").astype(int)
    # At a common effective date: latest filing, latest reported period, standalone
    # quarter, amendment, latest start, then lexical accession. Never combine rows.
    selected = selected.sort_values([
        "effective_date", "_filed", "_period_end", "_quarter", "_amended",
        "_period_start", "accession",
    ], kind="stable").drop_duplicates("effective_date", keep="last")
    selected = selected.drop(columns=["ticker", *sorted(internal)])
    rename = {c: f"fundamental_{c}" for c in (*METADATA_COLUMNS, "effective_date") if c != "ticker"}
    return selected.rename(columns=rename).reset_index(drop=True)

def build_research_dataset(
    market: pd.DataFrame, fundamentals: pd.DataFrame, *, allow_empty: bool = False,
) -> pd.DataFrame:
    """Keep every market row and attach the latest whole eligible observation.

    effective_date is the first *observed* market session strictly after filing;
    pre-window filings are left-censored to the first session in this dataset.
    """
    checked = _market(market)
    return _join(checked, _observations(fundamentals, parse_dates(checked.date), allow_empty=allow_empty))

def build_fundamental_features(fundamentals: pd.DataFrame) -> pd.DataFrame:
    """Compute frozen snapshots at each filing; no daily pct_change or YTD flows."""
    fundamentals = normalize_fundamental_dates(fundamentals)
    quality = validate_fundamentals(fundamentals)
    if not quality["valid"]:
        raise ValueError(f"Invalid fundamentals: {quality['errors']}")
    reserved = set(PAYLOAD_COLUMNS) | {"effective_date", "selected_for_daily", "selected_for_stage5",
                "selected_for_q", "selected_for_fy", "selected_for_bs",
                "effective_date_basis", "effective_date_is_sample_truncated"}
    if reserved & set(fundamentals):
        raise ValueError("Fundamentals already contain Stage 6 reserved columns")
    eligible = fundamentals[fundamentals.data_period_type.isin(["quarterly", "annual"])].copy()
    # All sorting, cutoff and period comparisons operate on typed dates. The
    # canonical strings above are only the boundary of the Stage 4 validator.
    for column in FUNDAMENTAL_DATE_COLUMNS:
        eligible[column] = parse_dates(eligible[column])
    eligible = eligible.sort_values([
        "filing_date", "period_end", "period_start", "accession", "data_period_type",
    ], kind="stable").reset_index(drop=True)
    computed = []
    for _, row in eligible.iterrows():
        values: dict[str, Any] = {c: np.nan for c in FEATURE_COLUMNS}
        prefix = "q" if row.data_period_type == "quarterly" else "fy"
        for name, numerator in RATIO_FIELDS.items():
            values[f"{prefix}_{name}"] = _divide(row[numerator], row.revenue)
        for name, (numerator, denominator) in BALANCE_RATIOS.items():
            values[name] = _divide(row[numerator], row[denominator])
        known = eligible[eligible.filing_date.le(row.filing_date)]
        reference, status = _reference(row, known)
        values["yoy_comparison_status"] = status
        values.update({c: None for c in REFERENCE_COLUMNS})
        if reference is not None:
            if reference.filing_date > row.filing_date:
                raise ValueError("Historical reference filing is later than current filing")
            values.update({f"yoy_reference_{c}": reference[c] for c in REFERENCE_FIELDS})
            for name, field in GROWTH_FIELDS.items():
                values[f"{prefix}_{name}_growth_yoy"] = _divide(row[field], reference[field], growth=True)
        computed.append(values)
    derived = pd.DataFrame(computed, columns=SNAPSHOT_PAYLOAD_COLUMNS)
    derived = derived.astype({c: float for c in FEATURE_COLUMNS})
    result = pd.concat([eligible, derived], axis=1)
    for column in date_columns(result.columns):
        result[column] = canonical_dates(result[column], allow_missing=True)
    return result

def _market_from_research(research: pd.DataFrame, fundamentals: pd.DataFrame) -> pd.DataFrame:
    missing = set(PROCESSED_COLUMNS) - set(research)
    if missing:
        raise ValueError(f"Missing Stage 3 columns: {sorted(missing)}")
    if set(PAYLOAD_COLUMNS) & set(research):
        raise ValueError("Research input already contains Stage 6 columns")
    if not validate_features(research.assign(date=parse_dates(research.date).dt.date))["valid"]:
        raise ValueError("Stage 3 market feature validation failed")
    fundamental_columns = {
        f"fundamental_{c}" if c in METADATA_COLUMNS else c
        for c in fundamentals if c != "ticker"
    } | {"fundamental_effective_date", *AGE_COLUMNS}
    market = research.drop(columns=list(fundamental_columns & set(research))).copy()
    quality = validate_research_dataset(_canonical_research(research), market, fundamentals)
    if not quality["valid"]:
        raise ValueError(f"Stage 5 source alignment failed: {quality['errors']}")
    return market
